RECORD = {
    "id": "JAH-NMU4-000001",
    "name": "Sardor",
    "kind": "first-name",
    "meaning": "Sardor is a masculine given name in Uzbek. Meaning: A leading modern boys' name.."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Sar")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

